@startuml
class Ingredient {
  +name : string
  +measuringUnit : string
  +quantityInStock : float
}

class Dish {
  +name : string
  +numericIdentifier : int
}

class Table {
  +numericIdentifier : int
  +maximumAmmountOfPeople : int
}

class Meal {
  +date : date
  +startTime : time
  +endTime : time
}

class Waiter {
  +numericIdentifier : int
  +name : string
  +address : string
  +phoneNumber : string
}

class Client {
  +taxIdentificationNumber : string
  +name : string
  +address : string
}

class DishIngredient {
  +quantity : float
}

class MealDish {
  +quantity : float
}

Dish "1" -- "*" DishIngredient : contains
Ingredient "1" -- "*" DishIngredient : used in
Dish "*" -- "*" Meal : consumed in
Meal "1" -- "*" MealDish : includes
Dish "1" -- "*" MealDish : part of
Meal "0..1" -- "1" Client : consumed by
Meal "*" -- "1" Waiter : responsible waiter
Meal "*" -- "1" Table : takes place at
@enduml

